package com.bank.portal.service;
import com.bank.portal.domain.*; import com.bank.portal.repository.CreditScoreEventRepository; import java.math.*; import java.time.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class CreditHealthService { private final CreditScoreEventRepository events;
 @Transactional public void apply(Customer c,CreditCard card,CreditScoreEventType type,int points,String reference,String detail){if(events.existsByCustomerIdAndEventTypeAndReferenceKey(c.getId(),type,reference))return;CreditScoreEvent event=new CreditScoreEvent();event.setCustomer(c);event.setCard(card);event.setEventType(type);event.setPoints(points);event.setReferenceKey(reference);event.setDescription(detail);event.setEventDate(LocalDate.now());events.save(event);c.setCreditHealthScore(Math.max(300,Math.min(900,c.getCreditHealthScore()+points)));}
 @Transactional public void evaluateUtilization(CreditCard card){BigDecimal pct=card.getOutstandingAmount().multiply(BigDecimal.valueOf(100)).divide(card.getCreditLimit(),2,RoundingMode.HALF_UP);String ref="UTIL-"+card.getId()+"-"+YearMonth.now();if(pct.compareTo(BigDecimal.valueOf(95))>0)apply(card.getCustomer(),card,CreditScoreEventType.VERY_HIGH_UTILIZATION,-40,ref,"Utilization above 95%");else if(pct.compareTo(BigDecimal.valueOf(80))>0)apply(card.getCustomer(),card,CreditScoreEventType.HIGH_UTILIZATION,-25,ref,"Utilization above 80%");else if(pct.compareTo(BigDecimal.TEN)<0)apply(card.getCustomer(),card,CreditScoreEventType.VERY_LOW_UTILIZATION,15,ref,"Utilization below 10%");else if(pct.compareTo(BigDecimal.valueOf(30))<0)apply(card.getCustomer(),card,CreditScoreEventType.LOW_UTILIZATION,8,ref,"Utilization below 30%");}
}
